import json
import re
from collections import deque
from typing import Dict, List, Tuple, Any


CHOICE_RE = re.compile(r"^\d+\.\s*")


def _is_section_header(line: str) -> bool:
    return line.startswith("[") and line.endswith("]") and len(line) >= 3


def _parse_line_content(line: str) -> Tuple[str, str, str]:
    """Return (speaker, text, target) where target may be ''."""
    if "->" in line:
        left, right = line.split("->", 1)
        target = right.strip()
    else:
        left = line
        target = ""
    left = left.strip()
    if ":" in left:
        speaker, text = left.split(":", 1)
        return speaker.strip(), text.strip(), target
    return "", left.strip(), target


def _parse_choice_line(line: str) -> Tuple[str, str]:
    """Return (choice_text, target)."""
    if "->" not in line:
        raise ValueError(f"Choice line missing '->': {line}")
    left, right = line.split("->", 1)
    target = right.strip()
    left = CHOICE_RE.sub("", left.strip())
    return left.strip(), target


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []
    node_index: Dict[str, int] = {}

    current_id = None
    current_lines: List[str] = []

    def add_node(node_id: str, node: Dict[str, str]):
        if node_id in node_index:
            raise ValueError(f"Duplicate node id: {node_id}")
        node_index[node_id] = len(nodes)
        nodes.append(node)

    def process_block(node_id: str, block_lines: List[str]):
        if not block_lines:
            add_node(node_id, {"id": node_id, "text": "", "speaker": "", "type": "line"})
            return

        stripped_lines = [ln.strip() for ln in block_lines if ln.strip()]
        if not stripped_lines:
            add_node(node_id, {"id": node_id, "text": "", "speaker": "", "type": "line"})
            return

        is_choice_block = all(CHOICE_RE.match(ln) for ln in stripped_lines)

        if is_choice_block:
            add_node(node_id, {"id": node_id, "text": "", "speaker": "", "type": "choice"})
            for ln in stripped_lines:
                choice_text, target = _parse_choice_line(ln)
                edges.append({"from": node_id, "to": target, "text": choice_text})
        else:
            # Treat as a single line node; ignore any extra lines for now
            speaker, text, target = _parse_line_content(stripped_lines[0])
            add_node(node_id, {"id": node_id, "text": text, "speaker": speaker, "type": "line"})
            if target:
                edges.append({"from": node_id, "to": target, "text": ""})

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        if _is_section_header(line):
            if current_id is not None:
                process_block(current_id, current_lines)
            current_id = line[1:-1].strip()
            current_lines = []
        else:
            current_lines.append(line)

    if current_id is not None:
        process_block(current_id, current_lines)

    # Validation: edge targets must exist (allow empty targets only on the last node)
    node_ids = {n["id"] for n in nodes}
    last_node_id = nodes[-1]["id"] if nodes else None
    for e in edges:
        if e["to"] and e["to"] not in node_ids:
            raise ValueError(f"Edge target missing: {e['to']}")

    # Validation: all nodes reachable from the first node
    if nodes:
        start_id = nodes[0]["id"]
        graph = {}
        for e in edges:
            graph.setdefault(e["from"], []).append(e["to"])
        visited = set()
        q = deque([start_id])
        while q:
            nid = q.popleft()
            if nid in visited:
                continue
            visited.add(nid)
            for nxt in graph.get(nid, []):
                if nxt:
                    q.append(nxt)
        unreachable = [n["id"] for n in nodes if n["id"] not in visited]
        if unreachable:
            raise ValueError(f"Unreachable nodes: {', '.join(unreachable)}")

    return {"nodes": nodes, "edges": edges}


def _escape_dot(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def _write_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [shape=box,fontname=\"Helvetica\"];" ]
    for node in graph["nodes"]:
        nid = _escape_dot(node["id"])
        if node["type"] == "choice":
            label = node["id"]
            shape = "diamond"
        else:
            if node["speaker"]:
                label = f"{node['id']}\\n{node['speaker']}: {node['text']}"
            else:
                label = f"{node['id']}\\n{node['text']}"
            shape = "box"
        label = _escape_dot(label)
        lines.append(f"  \"{nid}\" [label=\"{label}\",shape={shape}];")

    for edge in graph["edges"]:
        frm = _escape_dot(edge["from"])
        to = _escape_dot(edge["to"])
        if edge["text"]:
            label = _escape_dot(edge["text"])
            lines.append(f"  \"{frm}\" -> \"{to}\" [label=\"{label}\"]; ")
        else:
            lines.append(f"  \"{frm}\" -> \"{to}\";")

    lines.append("}")
    return "\n".join(lines)


def main():
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()
    graph = parse_script(text)
    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)
    dot = _write_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)


if __name__ == "__main__":
    main()
